const pageNames=['index','people','research','contact'];
const page=pageNames.includes(document.body.dataset.page)?document.body.dataset.page:'index';
let lang=new URLSearchParams(location.search).get('lang');
if(!['en','zh'].includes(lang)){try{lang=localStorage.getItem('hcai-language')}catch{}}if(!['en','zh'].includes(lang))lang='en';
const link=(p)=>`${p}.html?lang=${lang}`;
const ext=(url,label,cls='')=>`<a href="${url}" target="_blank" rel="noopener noreferrer" class="${cls}">${label}</a>`;
function render(){
 const t=text[lang];const pi=pageNames.indexOf(page);document.documentElement.lang=lang==='zh'?'zh-CN':'en';document.title=`${t.nav[pi]} | Human-Centered AI LAB · SJTU`;
 const header=`<header id="top" class="minimal-header"><div class="header-brand"><a class="official-identity" href="https://gift.sjtu.edu.cn/" target="_blank" rel="noopener noreferrer"><img src="assets/sjtu-gift-official.png" alt="上海交通大学校徽与校名 · 溥渊未来技术学院院徽与院名 / Shanghai Jiao Tong University · Global Institute of Future Technology"></a><a class="lab-wordmark" href="${link('index')}" lang="en">Human-Centered AI LAB</a></div><div class="minimal-controls"><nav id="navigation" aria-label="${lang==='en'?'Main navigation':'主导航'}">${pageNames.map((p,i)=>`<a href="${link(p)}" ${page===p?'aria-current="page"':''}>${t.nav[i]}</a>`).join('')}</nav><div class="language" aria-label="Language / 语言"><button type="button" data-lang="en" aria-pressed="${lang==='en'}" lang="en">EN</button><span aria-hidden="true">/</span><button type="button" data-lang="zh" aria-pressed="${lang==='zh'}" lang="zh-CN">中</button></div></div></header>`;
 const source=`<p class="source-note">${t.source} ${ext(faculty,t.sourceLink)}${lang==='en'?'.':'。'}</p>`;
 let content='';

 if(page==='people')content=`<div class="page-intro"><h1>${t.peopleTitle}</h1></div><article class="person-profile"><div><img class="portrait" src="assets/ruigang-yang.jpg" alt="${t.name}"></div><div><div class="eyebrow director-label">${t.lead}</div><h2 class="person-name">${t.name}<span class="chinese-name">${t.otherName}</span></h2><p class="role director-role">${t.role}</p><p class="fellow">IEEE Fellow</p><p>${t.bio}</p></div></article><section class="faculty-section"><h2>${t.facultyHeading}</h2><article class="person-profile faculty-profile"><div><img class="portrait" src="assets/chenggang-wang.png" alt="${t.wangName}" loading="lazy"></div><div><h3 class="person-name">${t.wangName}<span class="chinese-name">${t.wangOtherName}</span></h3><p class="role">${t.wangRole}</p><p>${t.wangBio}</p></div></article></section>`;
 if(page==='people')content+=`<div class="student-sections">${['Postdoc','Ph.D.','Master','Undergraduate','Visiting Student'].map(group=>`<section class="student-section"><h2 lang="en">${group}</h2><div class="student-grid">${students.filter(s=>s.group===group).map(s=>`<article class="student-card"><h3>${s.website?ext(s.website,`${s.en} (${s.zh})`):`${s.en} (${s.zh})`}</h3>${s.affiliation?`<p>${s.affiliation}</p>`:''}${(lang==='en'?s.directionEn:s.directionZh)?`<p>${lang==='en'?s.directionEn:s.directionZh}</p>`:''}</article>`).join('')}</div></section>`).join('')}</div>`;
 if(page==='research')content=`<div class="page-intro"><h1>${t.researchTitle}</h1></div><div class="project-list">${publications.map((p,i)=>`<article class="project-row${p.image?'':' project-row-text'}" id="${p.id}">${p.image?`<a class="project-image" href="${p.paper}" target="_blank" rel="noopener noreferrer" aria-label="${p.title}"><img src="${p.image}" alt="${p.imageAlt}" ${i>2?'loading="lazy"':''}></a>`:''}<div class="project-details"><h2>${ext(p.paper,p.title)}</h2><p class="project-authors">${p.authors.join(', ')}</p><p class="project-venue">${p.venue}${p.year?' · '+p.year:''}</p><div class="project-links">${[[p.project,lang==='en'?'Webpage':'项目主页'],[p.paper,lang==='en'?'Paper':'论文'],[p.code,lang==='en'?'Code':'代码']].filter(([url])=>url).map(([url,label])=>ext(url,label)).join('')}</div></div></article>`).join('')}</div>`;
 if(page==='contact')content=`<div class="page-intro"><h1>${t.contactTitle}</h1></div><div class="contact-content"><section class="contact-information"><dl class="contact-details"><div><dt>${t.email}</dt><dd><a href="mailto:ryang2@sjtu.edu.cn">ryang2@sjtu.edu.cn</a></dd></div><div><dt>${t.office}</dt><dd>${t.officeText}</dd></div><div><dt>${t.address}</dt><dd>${t.university}<br>${t.addressText}</dd></div></dl></section><section class="join-us"><h2 lang="en">Join us</h2><p>${t.joinText} <a href="mailto:ryang2@sjtu.edu.cn">ryang2@sjtu.edu.cn</a>${lang==='en'?'.':'。'}</p></section></div>`;
 const groupGallery=`<section class="group-gallery" aria-label="${lang==='en'?'Lab group photos':'实验室合照'}"><div class="highlight-grid" tabindex="0" role="region" aria-label="${lang==='en'?'Group photo carousel':'合照轮播'}">${[1,2,3].map(i=>`<img src="assets/group/${i}.webp" width="1707" height="1280" alt="${lang==='en'?'HCAI LAB group photo':'HCAI LAB 团队合照'} ${i}" draggable="false">`).join('')}</div><div class="highlight-dots">${[1,2,3].map(i=>`<button type="button" data-slide="${i-1}" aria-label="${lang==='en'?'Show photo':'查看合照'} ${i}" aria-pressed="${i===2}"><span></span></button>`).join('')}</div></section>`;
 const demoVideo=(i,label)=>`<video autoplay muted loop playsinline preload="metadata" poster="assets/highlights/feishu-${i}.jpg" aria-label="${label}"><source src="assets/highlights/feishu-${i}.mp4" type="video/mp4"></video>`;
 const home=page==='index'?`<main id="main" class="home-page">
  <section class="home-reel" aria-label="${lang==='en'?'Robot demonstrations':'机器人演示'}"><div class="highlight-grid" tabindex="0" role="region" aria-label="${lang==='en'?'Video carousel':'视频轮播'}">${[1,3,2,4,5].map((video,i)=>demoVideo(video,`${lang==='en'?'Robot demonstration':'机器人演示'} ${i+1}`)).join('')}</div><div class="highlight-dots">${[1,2,3,4,5].map(i=>`<button type="button" data-slide="${i-1}" aria-label="${lang==='en'?'Show video':'查看视频'} ${i}" aria-pressed="${i===3}"><span></span></button>`).join('')}</div></section>
  <section class="lab-intro" aria-label="${lang==='en'?'About HCAI LAB':'实验室简介'}"><div class="lab-intro-inner"><p>${labIntro[lang]}</p></div></section>
  <section class="home-projects" aria-labelledby="highlights-title"><h2 id="highlights-title" lang="en">Highlights</h2><div class="home-project-list">${[
   {video:2,title:lang==='en'?'Humanoid jumping':'人形机器人跳跃'},
   {video:4,title:lang==='en'?'Handkerchief spinning':'转手绢',paperId:'spinsoft'},
   {video:5,title:lang==='en'?'Garment folding':'叠衣服',paperId:'simweaver'}
  ].map(item=>{const pub=item.paperId?publications.find(p=>p.id===item.paperId):null;return `<article class="home-project"><div class="home-project-media">${demoVideo(item.video,item.title)}</div><div class="home-project-info">${pub?`<h4>${ext(pub.paper,pub.title)}</h4><p class="home-project-authors">${pub.authors.join(', ')}</p><p class="home-project-venue">${pub.venue} · ${pub.year}</p><div class="project-links">${[[pub.paper,lang==='en'?'Paper':'论文'],[pub.project,lang==='en'?'Webpage':'项目主页'],[pub.code,lang==='en'?'Code':'代码']].filter(([url])=>url).map(([url,label])=>ext(url,label)).join('')}</div>`:''}</div></article>`}).join('')}</div></section>
 </main>`:'';
 document.getElementById('app').innerHTML=header+(page==='index'?home:page==='people'?`<main id="main" class="people-page">${groupGallery}<div class="wrap">${content}</div></main>`:`<main id="main" class="wrap">${content}</main>`);
 document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>{lang=b.dataset.lang;try{localStorage.setItem('hcai-language',lang)}catch{}const url=new URL(location.href);url.searchParams.set('lang',lang);history.replaceState(null,'',url);render()}));

 const track=document.querySelector('.highlight-grid');
 if(track){
  const slides=[...track.querySelectorAll('video, img')];
  const dots=[...document.querySelectorAll('[data-slide]')];
  const position=i=>slides[i].offsetLeft-track.offsetLeft-(track.clientWidth-slides[i].clientWidth)/2;
  const current=()=>slides.reduce((best,_,i)=>Math.abs(track.scrollLeft-position(i))<Math.abs(track.scrollLeft-position(best))?i:best,0);
  const go=i=>track.scrollTo({left:position(Math.max(0,Math.min(slides.length-1,i))),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
  track.scrollLeft=position(page==='index'?2:1);
  dots.forEach((dot,i)=>dot.addEventListener('click',()=>go(i)));
  track.addEventListener('scroll',()=>{const active=current();dots.forEach((d,i)=>d.setAttribute('aria-pressed',String(i===active)))},{passive:true});
  track.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();go(current()+(e.key==='ArrowRight'?1:-1))}});
  let drag=null;
  track.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'||e.button!==0)return;drag={x:e.clientX,left:track.scrollLeft,index:current()};track.setPointerCapture(e.pointerId);track.classList.add('dragging')});
  track.addEventListener('pointermove',e=>{if(drag)track.scrollLeft=drag.left+drag.x-e.clientX});
  const finish=e=>{if(!drag)return;const delta=drag.x-e.clientX;const target=drag.index+(Math.abs(delta)>60?Math.sign(delta):0);drag=null;track.classList.remove('dragging');go(target)};
  track.addEventListener('pointerup',finish);track.addEventListener('pointercancel',()=>{drag=null;track.classList.remove('dragging')});
 }
}
render();
